//! Benchmarks of the shielded pool pallet.

use super::*;
use alloc::{boxed::Box, vec};
use codec::Decode;
use frame_benchmarking::v2::*;
use frame_support::{
	pallet_prelude::TransactionSource,
	traits::{fungible::Mutate, Authorize, Get},
	BoundedVec,
};
use frame_system::RawOrigin;
use tessera_shielded::tree::Frontier;

/// A private transfer of two notes with a fee of 1 TESS, generated by the `benchmark_fixture`
/// test.
const FIXTURE: &[u8] = include_bytes!("fixtures/transfer.scale");

fn transaction<T: Config>() -> ShieldedTransaction<T::AccountId> {
	let transaction = ShieldedTransaction::<T::AccountId>::decode(&mut &FIXTURE[..])
		.expect("the fixture is a valid transaction; qed");
	// A tree with many notes: appending costs the most when it updates many levels.
	let mut tree = Frontier::default();
	tree.size = (1 << 31) - 1;
	Tree::<T>::put(tree);
	let mut roots = vec![Digest::ZERO; T::RootHistory::get() as usize - 1];
	roots.push(transaction.anchor);
	Roots::<T>::put(BoundedVec::truncate_from(roots));
	PoolBalance::<T>::put(BalanceOf::<T>::from(MAX_VALUE));
	transaction
}

#[benchmarks]
mod benchmarks {
	use super::*;

	#[benchmark]
	fn authorize_transact() -> Result<(), BenchmarkError> {
		let call = Call::<T>::transact { transaction: Box::new(transaction::<T>()) };

		#[block]
		{
			call.authorize(TransactionSource::External)
				.ok_or("the call must be authorized")?
				.map_err(|_| "the transaction must be valid")?;
		}

		Ok(())
	}

	#[benchmark]
	fn transact() {
		let transaction = transaction::<T>();
		let nullifier = transaction.nullifiers[0];

		#[extrinsic_call]
		_(RawOrigin::Authorized, Box::new(transaction));

		assert!(Nullifiers::<T>::contains_key(nullifier));
	}

	#[benchmark]
	fn shield_burn() -> Result<(), BenchmarkError> {
		let caller: T::AccountId = whitelisted_caller();
		T::Currency::set_balance(&caller, BalanceOf::<T>::from(MAX_VALUE));

		#[block]
		{
			T::Currency::burn_from(
				&caller,
				BalanceOf::<T>::from(1_000_000u64),
				frame_support::traits::tokens::Preservation::Preserve,
				frame_support::traits::tokens::Precision::Exact,
				frame_support::traits::tokens::Fortitude::Polite,
			)?;
		}

		Ok(())
	}

	impl_benchmark_test_suite!(Pallet, crate::mock::new_test_ext(), crate::mock::Test);
}
